16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164: '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Transient
64	    private String customerCode;
65	
66	    @Transient
67	    private Integer namesakeCount;
68	
69	    @Transient
70	    private Boolean bulkSignupWarning;
71	
72	    @Transient
73	    private Integer householdSize;
74	
75	    @Transient
76	    private Integer possibleDuplicateOf;
77	
78	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
79	    private Set<Pet> pets;
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
96	
97	    public String getTelephone() {
98	        return this.telephone;
99	    }
100	
101	    public void setTelephone(String telephone) {
102	        this.telephone = telephone;
103	    }
104	
105	    public String getEmail() {
106	        return this.email;
107	    }
108	
109	    /** Store the email lower-cased so it is persisted and returned in canonical form. */
110	    public void setEmail(String email) {
111	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
112	    }
113	
114	    public String getPostcode() {
115	        return this.postcode;
116	    }
117	
118	    public void setPostcode(String postcode) {
119	        this.postcode = postcode;
120	    }
121	
122	    public LocalDate getRegistrationDate() {
123	        return this.registrationDate;
124	    }
125	
126	    /** Default a missing registration date to the server's current date. */
127	    public void setRegistrationDate(LocalDate registrationDate) {
128	        this.registrationDate = BusinessDay.adjust((registrationDate == null) ? LocalDate.now() : registrationDate);
129	    }
130	
131	    public LocalDate getBirthDate() {
132	        return this.birthDate;
133	    }
134	
135	    public void setBirthDate(LocalDate birthDate) {
136	        this.birthDate = birthDate;
137	    }
138	
139	    public String getCustomerCode() {
140	        return this.customerCode;
141	    }
142	
143	    public void setCustomerCode(String customerCode) {
144	        this.customerCode = customerCode;
145	    }
146	
147	    public Integer getNamesakeCount() {
148	        return this.namesakeCount;
149	    }
150	
151	    public void setNamesakeCount(Integer namesakeCount) {
152	        this.namesakeCount = namesakeCount;
153	    }
154	
155	    public Boolean getBulkSignupWarning() {
156	        return this.bulkSignupWarning;
157	    }
158	
159	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
160	        this.bulkSignupWarning = bulkSignupWarning;
161	    }
162	
163	    public Integer getHouseholdSize() {
164	        return this.householdSize;
165	    }
166	
167	    public void setHouseholdSize(Integer householdSize) {
168	        this.householdSize = householdSize;
169	    }
170	
171	    public Integer getPossibleDuplicateOf() {
172	        return this.possibleDuplicateOf;
173	    }
174	
175	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
176	        this.possibleDuplicateOf = possibleDuplicateOf;
177	    }
178	
179	    public Boolean getPossibleDuplicate() {
180	        return this.possibleDuplicateOf != null;
181	    }
182	
183	    protected Set<Pet> getPetsInternal() {
184	        if (this.pets == null) {
185	            this.pets = new HashSet<>();
186	        }
187	        return this.pets;
188	    }
189	
190	    protected void setPetsInternal(Set<Pet> pets) {
191	        this.pets = pets;
192	    }
193	
194	    public List<Pet> getPets() {
195	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
196	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
197	        return Collections.unmodifiableList(sortedPets);
198	    }
199	
200	    public void setPets(List<Pet> pets) {
201	        this.pets = new HashSet<>(pets);
202	    }
203	
204	    public void addPet(Pet pet) {
205	        getPetsInternal().add(pet);
206	        pet.setOwner(this);
207	    }
208	
209	    /**
210	     * Return the Pet with the given name, or null if none found for this Owner.
211	     *
212	     * @param name to test
213	     * @return true if pet name is already in use
214	     */
215	    public Pet getPet(String name) {
216	        return getPet(name, false);
217	    }
218	
219	    /**
220	     * Return the Pet with the given name, or null if none found for this Owner.
221	     *
222	     * @param name to test
223	     * @return true if pet name is already in use
224	     */
225	    public Pet getPet(String name, boolean ignoreNew) {
226	        name = name.toLowerCase();
227	        for (Pet pet : getPetsInternal()) {
228	            if (!ignoreNew || !pet.isNew()) {
229	                String compName = pet.getName();
230	                compName = compName.toLowerCase();
231	                if (compName.equals(name)) {
232	                    return pet;
233	                }
234	            }
235	        }
236	        return null;
237	    }
238	
239	    public Pet getPet(Integer petId) {
240	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
241	    }
242	
243	    @Override
244	    public String toString() {
245	        return new ToStringCreator(this)
246	
247	            .append("id", this.getId())
248	            .append("new", this.isNew())
249	            .append("lastName", this.getLastName())
250	            .append("firstName", this.getFirstName())
251	            .append("address", this.address)
252	            .append("city", this.city)
253	            .append("telephone", this.telephone)
254	            .toString();
255	    }
256	}
