16	package org.springframework.samples.petclinic.service;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.util.Collection;
22	import java.util.HexFormat;
23	import java.util.Locale;
24	
25	import org.springframework.samples.petclinic.model.Owner;
26	
27	/**
28	 * Detects owners that belong to the same household. The household is keyed on the
29	 * normalised last name and the postcode, so any two owners sharing those values belong
30	 * to the same household without coordination.
31	 */
32	public final class HouseholdMatcher {
33	
34	    private HouseholdMatcher() {
35	    }
36	
37	    /**
38	     * A stable identifier shared by every owner in the same household: the first 12 hex
39	     * characters of SHA-256 over {@code normalizedLastName + '|' + postcode}.
40	     */
41	    public static String householdId(Owner owner) {
42	        String key = normalize(owner.getLastName()) + "|" + (owner.getPostcode() == null ? "" : owner.getPostcode());
43	        return hex12(key);
44	    }
45	
46	    /**
47	     * True when an existing owner already belongs to this owner's household and the owner
48	     * has not declared shared-household membership. A declared member (sharesHousehold) is
49	     * allowed through rather than rejected as a household duplicate.
50	     */
51	    public static boolean isHouseholdDuplicate(Collection<Owner> owners, Owner owner, Boolean sharesHousehold) {
52	        return !Boolean.TRUE.equals(sharesHousehold)
53	            && owners.stream().anyMatch(o -> sameHousehold(o, owner));
54	    }
55	
56	    /** The number of owners in this owner's household, counting the owner itself. */
57	    public static int householdSize(Collection<Owner> owners, Owner owner) {
58	        return (int) owners.stream().filter(o -> sameHousehold(o, owner)).count() + 1;
59	    }
60	
61	    /**
62	     * The id of an owner this one may soft-duplicate, or {@code null}. A declared household
63	     * member is never a suspected duplicate.
64	     */
65	    public static Integer possibleDuplicateOf(Collection<Owner> owners, Owner owner, Boolean sharesHousehold) {
66	        return Boolean.TRUE.equals(sharesHousehold) ? null : PossibleDuplicateMatcher.matchId(owners, owner);
67	    }
68	
69	    private static boolean sameHousehold(Owner a, Owner b) {
70	        return householdId(a).equals(householdId(b));
71	    }
72	
73	    private static String hex12(String key) {
74	        try {
75	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
76	            return HexFormat.of().formatHex(digest, 0, 6);
77	        }
78	        catch (NoSuchAlgorithmException e) {
79	            throw new IllegalStateException(e);
80	        }
81	    }
82	
83	    private static String normalize(String value) {
84	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
85	    }
86	}
