16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Map;
19	
20	/**
21	 * Derives an owner's locality (canonical region) from its city using a fixed
22	 * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning
23	 * "UNKNOWN" for any city not in the table.
24	 */
25	public final class LocalityResolver {
26	
27	    private static final Map<String, String> CITY_REGION =
28	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
29	
30	    /** Postcode hundreds-prefix (postcode / 100) -&gt; region, one per known range. */
31	    private static final Map<Integer, String> POSTCODE_REGION =
32	        Map.of(20, "NSW", 30, "VIC", 40, "QLD");
33	
34	    private LocalityResolver() {
35	    }
36	
37	    public static String locality(String city) {
38	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
39	    }
40	
41	    /**
42	     * Prefer the postcode's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
43	     * falling back to the city-to-region table when the postcode is absent or in no
44	     * known range.
45	     */
46	    public static String locality(String city, String postcode) {
47	        if (postcode != null) {
48	            String region = POSTCODE_REGION.get(Integer.parseInt(postcode) / 100);
49	            if (region != null) {
50	                return region;
51	            }
52	        }
53	        return locality(city);
54	    }
55	}
