1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java((owner.getFirstName().charAt(0) + \".\" + owner.getLastName().charAt(0) + \".\").toUpperCase())")
24	    @Mapping(target = "householdId", expression = "java(org.springframework.samples.petclinic.service.HouseholdMatcher.householdId(owner))")
25	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.service.IdentityKey.of(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.service.CheckDigit.of(owner.getCustomerCode()))")
27	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
28	    @Mapping(target = "membershipPoints", expression = "java(org.springframework.samples.petclinic.service.MembershipPoints.of(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(org.springframework.samples.petclinic.service.MembershipLevel.of(owner))")
30	    @Mapping(target = "locality", expression = "java(owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-')))")
31	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.service.RegionTimezone.of(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
33	    @Mapping(target = "ageBand", expression = "java(org.springframework.samples.petclinic.service.AgeBand.of(owner))")
34	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.service.TelephoneFormatter.display(owner.getTelephone()))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    Owner toOwner(OwnerDto ownerDto);
38	
39	    @Mapping(target = "id", ignore = true)
40	    @Mapping(target = "pets", ignore = true)
41	    @Mapping(target = "telephone", qualifiedByName = "normalizeTelephone")
42	    @Mapping(target = "address", expression = "java(org.springframework.samples.petclinic.service.AddressNormalizer.normalize(ownerDto.getAddress()))")
43	    @Mapping(target = "postcode", expression = "java(org.springframework.samples.petclinic.service.PostcodeValidator.validate(ownerDto.getCity(), ownerDto.getPostcode()))")
44	    @Mapping(target = "registrationDate", expression = "java(org.springframework.samples.petclinic.service.RegistrationDateValidator.validate(ownerDto.getRegistrationDate()))")
45	    @Mapping(target = "email", expression = "java(org.springframework.samples.petclinic.service.DisposableEmailDomain.validate(ownerDto.getEmail()))")
46	    Owner toOwner(OwnerFieldsDto ownerDto);
47	
48	    /**
49	     * Normalise a telephone to E.164 for storage: keep an explicit leading '+' and country
50	     * code when present, otherwise assume '+61' and drop a single leading national '0'.
51	     * Spaces, dashes and brackets are stripped; the result must have 8 to 15 digits after
52	     * the '+', else the number is rejected as invalid.
53	     */
54	    @Named("normalizeTelephone")
55	    default String normalizeTelephone(String telephone) {
56	        if (telephone == null) {
57	            return null;
58	        }
59	        boolean international = telephone.trim().startsWith("+");
60	        String digits = telephone.replaceAll("\\D", "");
61	        if (!international) {
62	            if (digits.startsWith("0")) {
63	                digits = digits.substring(1);
64	            }
65	            digits = "61" + digits;
66	        }
67	        if (digits.length() < 8 || digits.length() > 15) {
68	            throw new IllegalArgumentException("Telephone cannot form a valid E.164 number: " + telephone);
69	        }
70	        org.springframework.samples.petclinic.service.E164NationalLength.check(digits);
71	        return "+" + digits;
72	    }
73	
74	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
75	
76	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
77	
78	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
79	        OwnerPageDto ownerPageDto = new OwnerPageDto();
80	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
81	        ownerPageDto.setPage(ownerPage.getNumber());
82	        ownerPageDto.setSize(ownerPage.getSize());
83	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
84	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
85	        return ownerPageDto;
86	    }
87	}
