16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Collection;
19	import java.util.Objects;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	
23	/**
24	 * Detects a soft duplicate: an owner that is not a hard duplicate but shares an existing
25	 * owner's last name (case-insensitive) and postcode while using a different telephone.
26	 * Returns the id of the first such existing owner, or {@code null} when there is none.
27	 */
28	public final class PossibleDuplicateMatcher {
29	
30	    private PossibleDuplicateMatcher() {
31	    }
32	
33	    public static Integer matchId(Collection<Owner> existing, Owner owner) {
34	        if (owner.getPostcode() == null || owner.getLastName() == null) {
35	            return null;
36	        }
37	        return existing.stream()
38	            .filter(o -> owner.getLastName().equalsIgnoreCase(o.getLastName())
39	                && owner.getPostcode().equals(o.getPostcode())
40	                && !Objects.equals(owner.getTelephone(), o.getTelephone()))
41	            .map(Owner::getId)
42	            .findFirst()
43	            .orElse(null);
44	    }
45	}
