16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Collection;
19	import java.util.Objects;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	
23	/**
24	 * The single derived key that consolidates owner duplicate detection. It is exposed as
25	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Because the
26	 * telephone is part of the key, two members of the same household with different telephones
27	 * yield different keys and are both allowed; a new owner is rejected as a duplicate only when
28	 * it collides with an existing owner on the same telephone and email.
29	 */
30	public final class IdentityKey {
31	
32	    private IdentityKey() {
33	    }
34	
35	    public static String of(Owner owner) {
36	        return owner.getTelephone() + "|" + email(owner) + "|" + HouseholdMatcher.householdId(owner);
37	    }
38	
39	    public static boolean isDuplicate(Collection<Owner> owners, Owner owner) {
40	        return owners.stream().anyMatch(o -> Objects.equals(owner.getTelephone(), o.getTelephone())
41	            && email(owner).equals(email(o)));
42	    }
43	
44	    private static String email(Owner owner) {
45	        return owner.getEmail() == null ? "" : owner.getEmail();
46	    }
47	}
