20	import org.springframework.samples.petclinic.model.Owner;
21	
22	/**
23	 * Enforces the per-city owner cap: a city is full once it already holds
24	 * {@value #MAX_OWNERS_PER_CITY} owners, comparing city names case-insensitively.
25	 */
26	public final class CityCapacity {
27	
28	    public static final int MAX_OWNERS_PER_CITY = 50;
29	
30	    private CityCapacity() {
31	    }
32	
33	    public static boolean isFull(Collection<Owner> existing, Owner owner) {
34	        String city = owner.getCity();
35	        long inCity = existing.stream().filter(o -> city.equalsIgnoreCase(o.getCity())).count();
36	        return inCity >= MAX_OWNERS_PER_CITY;
37	    }
38	}
